const handlers = [authenticate, rateLimit, respondFromCache];

function dispatch(req) {
  for (const handler of handlers) {
    const result = handler(req);
    if (result !== PASS) return result;    // this handler consumed it
  }
  return UNHANDLED;                        // must be observed, not ignored
}

